"""The 20 hand-labelled steps. PROTOTYPE.
kind: "expr" (expression rewrite) or "eq" (equation line before -> after).
expected: EQUIV | NOT_EQUIV | DOMAIN (equal only under a domain restriction) | ONEWAY (after follows from before, not vice versa).
solve_for: variable for solution-set strategies (S5) when not the only free symbol.
"""
STEPS = [
 dict(id=1, topic="expand", before=r"(x+3)^2", after=r"x^2+6x+9", kind="expr", expected="EQUIV",
      why="(x+3)^2 = x^2+2*3x+9. Polynomial identity."),
 dict(id=2, topic="expand, mistake: dropped cross term", before=r"(x-2)^2", after=r"x^2-4", kind="expr", expected="NOT_EQUIV",
      why="(x-2)^2 = x^2-4x+4. At x=0 the sides are 4 and -4."),
 dict(id=3, topic="expand, mistake: wrong sign", before=r"(x-2)(x+5)", after=r"x^2-3x-10", kind="expr", expected="NOT_EQUIV",
      why="(x-2)(x+5) = x^2+5x-2x-10 = x^2+3x-10. Student has -3x. At x=0 both give -10 but at x=1: -6 vs -12."),
 dict(id=4, topic="factor", before=r"x^2-5x+6", after=r"(x-2)(x-3)", kind="expr", expected="EQUIV",
      why="(x-2)(x-3) = x^2-5x+6. Polynomial identity."),
 dict(id=5, topic="simplify fraction", before=r"\frac{2x+4}{6}", after=r"\frac{x+2}{3}", kind="expr", expected="EQUIV",
      why="Divide numerator and the constant denominator by 2. Constant divisor, so no domain change."),
 dict(id=6, topic="add fractions", before=r"\frac{x}{2}+\frac{x}{3}", after=r"\frac{5x}{6}", kind="expr", expected="EQUIV",
      why="x/2+x/3 = (3x+2x)/6 = 5x/6. Constant denominators, no domain change."),
 dict(id=7, topic="division-by-zero trap", before=r"\frac{x^2-1}{x-1}", after=r"x+1", kind="expr", expected="DOMAIN",
      why="Equal for every x != 1. At x=1 the left side is undefined (0/0) and the right side is 2. Valid only with x != 1."),
 dict(id=8, topic="trig identity", before=r"\cos^2 x-\sin^2 x", after=r"2\cos^2 x-1", kind="expr", expected="EQUIV",
      why="cos 2x = cos^2 x - sin^2 x = 2cos^2 x - 1 (use sin^2 = 1 - cos^2). True for all x."),
 dict(id=9, topic="solve linear", before=r"2x+3=7", after=r"x=2", kind="eq", expected="EQUIV",
      why="Both have solution set {2}. Residuals 2x-4 and x-2 are proportional (factor 2)."),
 dict(id=10, topic="solve linear, mistake: wrong sign", before=r"2x+3=7", after=r"2x=10", kind="eq", expected="NOT_EQUIV",
      why="Student added 3 instead of subtracting it. {2} vs {5}."),
 dict(id=11, topic="solve quadratic, mistake: dropped root", before=r"x^2-5x+6=0", after=r"x=2", kind="eq", expected="NOT_EQUIV",
      why="Solutions of the first are {2,3}; the student kept only 2. The step loses a root, so it is not an equivalence (it is implied backwards only)."),
 dict(id=12, topic="solve quadratic (factored form)", before=r"x^2-5x+6=0", after=r"(x-2)(x-3)=0", kind="eq", expected="EQUIV",
      why="Same polynomial, same roots {2,3}; residuals are identical."),
 dict(id=13, topic="rearrange formula", before=r"y=2x+3", after=r"x=\frac{y-3}{2}", kind="eq", expected="EQUIV", solve_for="x",
      why="Subtract 3, divide by 2: x=(y-3)/2. Same relation between x and y. Residuals y-2x-3 and x-(y-3)/2 are proportional (factor -2)."),
 dict(id=14, topic="squaring both sides (one-way)", before=r"\sqrt{x+1}=x-1", after=r"x+1=(x-1)^2", kind="eq", expected="ONEWAY",
      why="Squaring gives x^2-3x=0, roots {0,3}. Only x=3 satisfies the original (x=0 gives 1=-1), so after follows from before but not conversely."),
 dict(id=15, topic="squaring both sides (one-way), simple", before=r"x=2", after=r"x^2=4", kind="eq", expected="ONEWAY",
      why="{2} is a subset of {-2,2}: implied forwards, not backwards."),
 dict(id=16, topic="mistake: divide by x, lost root", before=r"x^2=3x", after=r"x=3", kind="eq", expected="NOT_EQUIV",
      why="x^2=3x has roots {0,3}. Dividing by x silently drops x=0 (division by zero)."),
 dict(id=17, topic="division-by-zero trap in an equation", before=r"\frac{x^2-1}{x-1}=2", after=r"x+1=2", kind="eq", expected="DOMAIN",
      why="Left has no solution (x=1 is excluded, any other x gives x+1=2 -> x=1). Right has {1}. The step is valid only if x != 1 is assumed, and then it shows no solution. Also one-way in solution-set terms (empty set implies {1} vacuously), so S5 reports WIDER here; that is not a mislabel."),
 dict(id=18, topic="Romanian ':' division", before=r"(4x+8):4", after=r"x+2", kind="expr", expected="EQUIV",
      why="(4x+8)/4 = x+2. Tests ':' -> \\div in the normalizer."),
 dict(id=19, topic="Romanian tg", before=r"\tg(x)\cdot\cos(x)", after=r"\sin(x)", kind="expr", expected="DOMAIN",
      why="tan x = sin x / cos x, so tan x cos x = sin x where cos x != 0. At x = pi/2 the left side is undefined and the right side is 1. Tests tg -> \\tan."),
 dict(id=20, topic="sqrt of a square", before=r"\sqrt{x^2}", after=r"x", kind="expr", expected="NOT_EQUIV",
      why="sqrt(x^2) = |x|, equal to x only for x >= 0. A classic student mistake: wrong for every x < 0 where both sides are defined. True only under the assumption x >= 0, which is not a removable singularity like #7, #17, #19."),
]
